struct MeshVertex
{
    Vec3f Position;
    Vec3f Color;
    Vec3f Normal;
    Vec2f TexCoord;
};

struct Mesh
{
    VkVertexInputAttributeDescription
        attributes[4];
};

MeshLayout
{
    Position Float3
    Normal Float3
    UV Float2
}

MeshDraw
{
    VkBuffer VertexBuffer;
}

