Chapter.Code:
graph.AddPass(
    "DirectionalShadow",
    {
        Write(
            shadowDepth,
            DepthAttachment)
    },
    [&]
    {
        backend.EncodeShadow(...);
    });

if (
    caps.SupportsTileDeferredPath)
{
    backend.EncodeNativeTilePath(...);
}
else
{
    EncodePortablePath(...);
}

ResourceHandle hdr =
    graph.CreateTexture(
        "Scene HDR",
        TextureDesc{...});

PassHandle geometry =
    graph.AddPass({
        .Name = "Geometry",
        .Queue = Graphics,

        .Writes = {
            {
                hdr,
                ColorAttachmentWrite
            }
        }
    });

PassHandle bloom =
    graph.AddPass({
        .Name = "Bloom",
        .Queue = Compute,

        .Reads = {
            {
                hdr,
                SampledRead
            }
        },

        .Writes = {
            {
                bloomHalf,
                StorageWrite
            }
        }
    });

struct CompiledPass
{
    PassID Pass;

    QueueClass Queue;

    std::vector<Barrier>
        PreBarriers;

    std::vector<QueueWait>
        Waits;

    std::vector<QueueSignal>
        Signals;

    std::vector<PhysicalResourceBinding>
        Resources;

    ExecuteCallback Execute;
};

if (
    capabilities.Supports(
        Feature::Bindless))

